source=rows(RUN/'comparison.jsonl');packet=json.loads((RUN/'POSTHOC_MATH_ANONYMOUS_PACKET.json').read_text());labels=json.loads((RUN/'POSTHOC_MATH_ASSISTANT_LABELS.json').read_text());mapping=json.loads((RUN/'POSTHOC_MATH_REVIEW_MAPPING_PRIVATE.json').read_text());assert {x['code'] for x in packet}==set(labels);assert len(mapping)==320
