    summary.append({'model':model,'denominator':64,'correct_final_observed':c['correct'],'wrong_or_no_target_observed':c['wrong'],'unclear_including_source_defect':c['unclear'],'assistant_correct_fraction_percent':100*c['correct']/64,'assistant_correct_or_unclear_upper_percent':100*(c['correct']+c['unclear'])/64,'v2_frozen_scorer_missed_assistant_correct':missed,'v2_frozen_scorer_false_positive_vs_review':fp,'status':'POSTHOC_ASSISTANT_REVIEW; not independent human gold; final answer only, not proof of correct full reasoning; no model selection'})
