write(RUN/'POSTHOC_SOURCE_DEFECTS_PRIVATE.json',{'reading_malformed':[{'id':r['id'],'reason':'Four parsed options include an embedded E/F/G list inside optionD; stem/passage appears mismatched. Flag all model outcomes for this source as uncertain; original64 denominator and score untouched'} for r in malformed],'math_source_unknown':[{'id':'gsm8k_train:1283','reason':'Ambiguous comparison of high pay per task versus total earnings; all5 retained uncertain in assistant audit'},{'id':'gsm8k_train:5496','reason':'Source reference12 contradicts stated arithmetic, which yields11; all5 retained uncertain in assistant audit; frozen source gold not changed after generation'}]})
write(REPORT/'PROTOCOL_VALIDITY.json',{'controlled_acceptance_passed':True,'controlled_cases':290,'natural_deployment_math_validity':'FAILED; cannot use frozen v2 mathematical accuracy for ability ranking','scorer_unchanged':sha(pathlib.Path(__file__).parent/'scoring_v2.py')==json.loads((RUN/'ACCEPTANCE_FROZEN.json').read_text())['scorer_sha256'],'math_implementation_bug':'Empty explicit-final heading followed by a correctly parsed multiline box is added as an invalid competing candidate. Historical results preserved; no scoring patch applied.','math_coverage_gap':'Natural complete narrative endings lack the narrow expected final marker; finite reference/controlled acceptance failed to cover adapted-model response styles.','synthetic_minimal_reproductions':repros,'new_math_full_assistant_review':{'unique_answers':len(labels),'occurrences':320,'blindness':'Packet names hidden, but prior aggregate/labelled cases seen. Not independent or strictly blind.','scope':'Final requested-answer evidence only; reasoning may be wrong despite a correct final number.','counts':summary},'reading_known_malformed_source_groups':len(malformed),'reading_source_uncertainty_bound_points_per_model':100/64,'reading_primary_scores_unchanged':'All64 sources retained; known malformed item makes up1/64. Scores and intervals are small-sample diagnostics, not formal confirmation.','math_newly_flagged_source_groups':2,'new_training_or_generation_for_repairs':0,'next_step_priority':'Future natural-response acceptance and source QA on unused sources before another scoring freeze. No parameter changes or new training authorized.'})
